import{_ as d,o,c as r,a as e}from"./app.DkoUFz-u.js";const p=JSON.parse('{"title":"欢迎来到服务端与架构","description":"","frontmatter":{},"headers":[],"relativePath":"backend/index.md","filePath":"backend/index.md"}'),n={name:"backend/index.md"};function s(a,t,i,c,g,l){return o(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="欢迎来到服务端与架构" tabindex="-1">欢迎来到服务端与架构 <a class="header-anchor" href="#欢迎来到服务端与架构" aria-label="Permalink to &quot;欢迎来到服务端与架构&quot;">​</a></h1><h2 id="java-学习路线" tabindex="-1">java 学习路线 <a class="header-anchor" href="#java-学习路线" aria-label="Permalink to &quot;java 学习路线&quot;">​</a></h2><p>以下是根据两个回答核心逻辑融合优化的 <strong>Java 就业导向优先级表</strong>，聚焦 <strong>「快速胜任 Spring Boot 业务开发」</strong> 场景，按 <strong>P0（不学写不出代码）、P1（先会用再深入）、P2（暂缓/按需补）</strong> 分级：</p><hr><h3 id="✅-p0-必学-不学寸步难行" tabindex="-1">✅ P0 必学（不学寸步难行） <a class="header-anchor" href="#✅-p0-必学-不学寸步难行" aria-label="Permalink to &quot;✅ P0 必学（不学寸步难行）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>大纲项</th><th>关键理由</th></tr></thead><tbody><tr><td><strong>3 面向对象编程</strong></td><td>Java 核心基石（封装/继承/多态/接口）</td></tr><tr><td><strong>4 异常处理</strong></td><td>健壮代码必备（try-catch-finally + 日志记录）</td></tr><tr><td><strong>7 泛型</strong></td><td>集合框架基石（<code>List&lt;String&gt;</code> 天天见）</td></tr><tr><td><strong>8 集合</strong></td><td>CRUD 本质是数据操作（ArrayList/HashMap 必须精通）</td></tr><tr><td><strong>15 Maven</strong></td><td>项目依赖管理和构建标准（<code>pom.xml</code> + 基础命令）</td></tr><tr><td><strong>22 Spring</strong></td><td>面试必考 + 框架核心（IoC 控制反转 + AOP 切面）</td></tr><tr><td><strong>23 Spring Boot</strong></td><td><strong>业务开发绝对主力</strong>（自动配置 + Starter 依赖 + 快速构建 REST API）</td></tr><tr><td><strong>21 Web 基础</strong></td><td>理解 HTTP 和 Servlet 模型（Spring MVC 底层支撑，<strong>但重点学 RESTful 即可</strong>）</td></tr></tbody></table><hr><h3 id="⚠️-p1-后期补-先跑通业务-再深入细节" tabindex="-1">⚠️ P1 后期补（先跑通业务，再深入细节） <a class="header-anchor" href="#⚠️-p1-后期补-先跑通业务-再深入细节" aria-label="Permalink to &quot;⚠️ P1 后期补（先跑通业务，再深入细节）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>大纲项</th><th>当前目标（够用就行）</th></tr></thead><tbody><tr><td><strong>9 IO</strong></td><td>掌握文件上传/下载工具类（如 Spring MultipartFile）</td></tr><tr><td><strong>10 日期与时间</strong></td><td>会用 <code>LocalDateTime</code> + <code>DateTimeFormatter</code> 处理业务日期</td></tr><tr><td><strong>11 单元测试</strong></td><td>JUnit 5 基础注解（<code>@Test</code> + <code>@BeforeEach</code>）+ Mockito 模拟依赖</td></tr><tr><td><strong>14 多线程</strong></td><td><strong>理解线程概念</strong> + Spring 线程池 <code>@Async</code> 注解（并发安全后续补）</td></tr><tr><td><strong>18 JDBC</strong></td><td>会写基础 SQL + 理解连接池（<strong>实际用 Spring Data JPA/MyBatis 封装</strong>）</td></tr><tr><td><strong>19 函数式编程</strong></td><td><strong>必会 Lambda + Stream API</strong>（集合过滤/映射/聚合）</td></tr><tr><td><strong>20 设计模式</strong></td><td>掌握单例、工厂、策略模式（看懂框架源码即可）</td></tr><tr><td><strong>17 JSON</strong></td><td>熟练使用 Jackson/Gson（API 参数解析 + 返回对象序列化）</td></tr></tbody></table><hr><h3 id="🛑-p2-可暂缓-非业务刚需-高级方向再学" tabindex="-1">🛑 P2 可暂缓（非业务刚需 / 高级方向再学） <a class="header-anchor" href="#🛑-p2-可暂缓-非业务刚需-高级方向再学" aria-label="Permalink to &quot;🛑 P2 可暂缓（非业务刚需 / 高级方向再学）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>大纲项</th><th>暂缓理由</th></tr></thead><tbody><tr><td><strong>5 反射</strong></td><td>框架底层机制，业务代码极少手写（看懂 <code>@Autowired</code> 原理即可）</td></tr><tr><td><strong>6 注解</strong></td><td>会使用 Spring 常用注解（<code>@Service</code>/<code>@GetMapping</code>），<strong>不学自定义注解</strong></td></tr><tr><td><strong>12 正则表达式</strong></td><td>复杂匹配现查现用（掌握 <code>String.matches()</code> 基础）</td></tr><tr><td><strong>13 加密与安全</strong></td><td>业务用现成方案（Spring Security/OAuth2 配着用，不深入算法）</td></tr><tr><td><strong>16 网络编程</strong></td><td>业务开发用 HTTP 工具（RestTemplate/Feign），不学 Socket/NIO</td></tr><tr><td><strong>17 XML</strong></td><td><strong>基本淘汰</strong>（仅需看懂配置文件）</td></tr><tr><td><strong>24 Spring Cloud</strong></td><td>微服务专题（工作后再学 Gateway/Feign/Nacos）</td></tr></tbody></table><hr><h3 id="🎯-高效学习路线-结合两个回答精华" tabindex="-1">🎯 高效学习路线（结合两个回答精华） <a class="header-anchor" href="#🎯-高效学习路线-结合两个回答精华" aria-label="Permalink to &quot;🎯 高效学习路线（结合两个回答精华）&quot;">​</a></h3><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">graph LR</span></span>
<span class="line"><span class="__shiki_140thh">A[死磕 P0 基础] --&gt; B[用 Spring Boot 做项目]</span></span>
<span class="line"><span class="__shiki_140thh">B --&gt; C[补 P1 工具链] </span></span>
<span class="line"><span class="__shiki_140thh">C --&gt; D[工作中迭代 P2]</span></span></code></pre></div><blockquote><p><strong>关键策略</strong>：</p><ol><li><strong>P0 阶段</strong>：OOP + 集合 + Spring Boot 为核心，2 周内写出第一个 REST API</li><li><strong>P1 阶段</strong>：在项目中边做边学（如用 Stream 优化代码/用 JUnit 测 Service）</li><li><strong>P2 阶段</strong>：遇到需求再学（如安全需求上 Spring Security / 微服务需求补 Cloud）</li></ol></blockquote><hr><h3 id="💡-优化要点说明" tabindex="-1">💡 优化要点说明 <a class="header-anchor" href="#💡-优化要点说明" aria-label="Permalink to &quot;💡 优化要点说明&quot;">​</a></h3><ol><li><strong>多线程</strong>：从原 P2 提升至 <strong>P1</strong>（业务必懂基础概念，否则调试困难）</li><li><strong>函数式编程</strong>：明确 <strong>Stream API 为 P1 重点</strong>（现代 Java 开发刚需）</li><li><strong>JSON</strong>：单独列为 <strong>P1 必会</strong>（比 XML 优先级更高）</li><li><strong>Web 基础</strong>：保留为 <strong>P0</strong> 但限定为 <strong>理解 HTTP 和 Servlet 模型</strong>（传统 JSP 可跳过）</li><li><strong>设计模式</strong>：精简为 <strong>“看懂框架源码”</strong> 级别（避免过早陷入理论）</li></ol><h2 id="ide-快键键" tabindex="-1">IDE 快键键 <a class="header-anchor" href="#ide-快键键" aria-label="Permalink to &quot;IDE 快键键&quot;">​</a></h2><p>以下 20 个快捷键是 <strong>IDEA 新手 1 小时就能全部记住并立刻提升效率</strong> 的“入门黄金组合”。按使用频率排序，先背前 10 个，再逐步扩展。</p><table tabindex="0"><thead><tr><th>场景</th><th>Windows / Linux</th><th>macOS</th><th>作用</th></tr></thead><tbody><tr><td><strong>万能搜索</strong></td><td><code>Double Shift</code></td><td><code>Double Shift</code></td><td>Search Everywhere（类、文件、符号、菜单都能搜）</td></tr><tr><td><strong>自动补全</strong></td><td><code>Ctrl + Space</code></td><td><code>⌃ Space</code></td><td>基本代码补全</td></tr><tr><td><strong>智能补全</strong></td><td><code>Ctrl + Shift + Space</code></td><td><code>⌃ ⇧ Space</code></td><td>只列出当前上下文最合适的补全</td></tr><tr><td><strong>生成代码</strong></td><td><code>Alt + Insert</code></td><td><code>⌘ N</code></td><td>快速生成 Getter/Setter、构造器、toString 等</td></tr><tr><td><strong>格式化</strong></td><td><code>Ctrl + Alt + L</code></td><td><code>⌘ ⌥ L</code></td><td>一键格式化当前文件</td></tr><tr><td><strong>优化 import</strong></td><td><code>Ctrl + Alt + O</code></td><td><code>⌘ ⌥ O</code></td><td>删除无用 import、排序</td></tr><tr><td><strong>快速修复/意图</strong></td><td><code>Alt + Enter</code></td><td><code>⌥ ↩</code></td><td>红灯泡：自动修复、导包、转换语法</td></tr><tr><td><strong>运行当前上下文</strong></td><td><code>Shift + F10</code></td><td><code>⌃ R</code></td><td>跑当前配置的 Run（Spring Boot、JUnit…）</td></tr><tr><td><strong>调试</strong></td><td><code>Shift + F9</code></td><td><code>⌃ D</code></td><td>Debug 当前配置</td></tr><tr><td><strong>单步跳过</strong></td><td><code>F8</code></td><td><code>Fn + F8</code></td><td>Debug 时&quot;Step Over&quot;（执行当前行）</td></tr><tr><td><strong>单步进入</strong></td><td><code>F7</code></td><td><code>Fn + F7</code></td><td>Debug 时&quot;Step Into&quot;（进入方法）</td></tr><tr><td><strong>单步跳出</strong></td><td><code>Shift + F8</code></td><td><code>Fn + ⇧ + F8</code></td><td>Debug 时&quot;Step Out&quot;（跳出方法）</td></tr><tr><td><strong>智能步入</strong></td><td><code>Shift + F7</code></td><td><code>Fn + ⇧ + F7</code></td><td>选择要进入的方法（多方法调用时）</td></tr><tr><td><strong>断点/取消</strong></td><td><code>Ctrl + F8</code></td><td><code>⌘ F8</code></td><td>在当前行加/取消断点</td></tr><tr><td><strong>重命名</strong></td><td><code>Shift + F6</code></td><td><code>⌘ F6</code></td><td>安全重命名变量/方法/类</td></tr><tr><td><strong>查找用法</strong></td><td><code>Alt + F7</code></td><td><code>⌥ F7</code></td><td>查看方法或变量在工程里所有被调用处</td></tr><tr><td><strong>全局文本搜索</strong></td><td><code>Ctrl + Shift + F</code></td><td><code>⌘ ⇧ F</code></td><td>Find in Path（支持正则）</td></tr><tr><td><strong>最近文件</strong></td><td><code>Ctrl + E</code></td><td><code>⌘ E</code></td><td>最近打开的文件列表</td></tr><tr><td><strong>注释/取消</strong></td><td><code>Ctrl + /</code></td><td><code>⌘ /</code></td><td>单行 <code>//</code> 注释</td></tr><tr><td><strong>块注释</strong></td><td><code>Ctrl + Shift + /</code></td><td><code>⌘ ⇧ /</code></td><td><code>/* ... */</code> 多行注释</td></tr></tbody></table><hr><h3 id="记忆口诀-背完不会忘" tabindex="-1">记忆口诀（背完不会忘） <a class="header-anchor" href="#记忆口诀-背完不会忘" aria-label="Permalink to &quot;记忆口诀（背完不会忘）&quot;">​</a></h3><ul><li><strong>双击 Shift</strong> 搜一切</li><li><strong>Alt + Enter</strong> 修一切</li><li><strong>Ctrl + Alt + L</strong> 让代码变美</li><li><strong>Shift + F10/F9</strong> 跑 vs 调</li><li><strong>F7/F8/Shift+F8</strong> 调试三连击</li></ul><h3 id="调试三连击详解" tabindex="-1">调试三连击详解： <a class="header-anchor" href="#调试三连击详解" aria-label="Permalink to &quot;调试三连击详解：&quot;">​</a></h3><table tabindex="0"><thead><tr><th>快捷键</th><th>名称</th><th>作用</th><th>使用场景</th></tr></thead><tbody><tr><td><strong>F8</strong></td><td>Step Over</td><td>执行当前行（不进入方法）</td><td>跳过已知安全的方法</td></tr><tr><td><strong>F7</strong></td><td>Step Into</td><td>进入方法内部</td><td>需要深入分析实现时</td></tr><tr><td><strong>Shift + F8</strong></td><td>Step Out</td><td>跳出当前方法</td><td>快速完成当前方法分析</td></tr></tbody></table><h3 id="额外实用技巧" tabindex="-1">额外实用技巧： <a class="header-anchor" href="#额外实用技巧" aria-label="Permalink to &quot;额外实用技巧：&quot;">​</a></h3><ol><li><p><strong>运行到光标</strong>：</p><ul><li><code>Alt + F9</code> (Win) / <code>⌥ + Fn + F9</code> (Mac)</li><li>无需设断点，直接运行到光标处</li></ul></li><li><p><strong>表达式求值</strong>：</p><ul><li><code>Alt + F8</code> (Win) / <code>⌥ + Fn + F8</code> (Mac)</li><li>调试时执行任意代码片段</li></ul></li><li><p><strong>条件断点</strong>：</p><ul><li>右键断点 → 设置条件（如 <code>username.equals(&quot;admin&quot;)</code>）</li></ul></li></ol><blockquote><p><strong>学习建议</strong>：</p><ol><li>先掌握前 10 个高频快捷键（万能搜索到调试）</li><li>重点练习调试三连击（F7/F8/Shift+F8）</li><li>每天刻意练习 3 个新快捷键</li><li>配合 <code>Ctrl + Shift + A</code> (Win) / <code>⌘ + ⇧ + A</code> (Mac) 查找任何操作快捷键</li></ol></blockquote><p>把这 20 个刻进肌肉记忆，IDEA 入门阶段就毕业了！调试效率直接翻倍 🚀</p>`,31)])])}const u=d(n,[["render",s]]);export{p as __pageData,u as default};
